import importlib.metadata as m,json,sys; ns=['torch','ray','vllm','gymnasium','numpy','pandas','PyYAML','pytest','transformers','safetensors','llumnix']; d={};
for n in ns:
 try: d[n]=m.version(n)
 except m.PackageNotFoundError: d[n]=None
print(json.dumps({'executable':sys.executable,'version':sys.version.split()[0],'selected_distributions':d},sort_keys=True))

